import { z } from 'zod';

export const OrderLineSchema = z.object({
  productId: z.string(),
  quantity: z.number(),
});

export const PlaceOrderSchema = z.object({
  email: z.string(),
  promoCode: z.string().optional(),
  lines: z.array(OrderLineSchema),
});

export type PlaceOrderInput = z.infer<typeof PlaceOrderSchema>;

